business as (select
    CAST(f.tenant_id AS String) AS `tenant_id`,
    CAST(f.action_key AS String) AS `action_key`,
    CAST(f.action_id AS Int64) AS `action_id`,
    CAST(f.action_version_key AS String) AS `source_action_version_key`,
    CAST(f.valid_from_at AS DateTime64(3, 'UTC')) AS `action_state_valid_from_at`,
    CAST(f.valid_to_at AS Nullable(DateTime64(3, 'UTC'))) AS `action_state_valid_to_at`,
    CAST(f.is_source_deleted AS Bool) AS `is_source_deleted`,
    CAST(f.action_type_id AS Nullable(Int64)) AS `action_type_id`,
    CAST(f.action_type_key AS Nullable(String)) AS `action_type_key`,
    CAST(f.action_type_version_key AS Nullable(String)) AS `action_type_version_key`,
    CAST(at.action_type_label AS Nullable(String)) AS `action_type_label`,
    CAST(f.company_key AS Nullable(String)) AS `company_key`,
    CAST(f.company_version_key AS Nullable(String)) AS `company_version_key`,
    CAST(f.company_id AS Nullable(Int64)) AS `company_id`,
    CAST(co.company_name AS Nullable(String)) AS `company_name`,
    CAST(f.contact_id AS Nullable(Int64)) AS `contact_id`,
    CAST(f.opportunity_key AS Nullable(String)) AS `opportunity_key`,
    CAST(f.opportunity_id AS Nullable(Int64)) AS `opportunity_id`,
    CAST(f.link_status AS String) AS `link_status`,
    CAST(f.created_at AS Nullable(DateTime64(3, 'UTC'))) AS `created_at`,
    CAST(f.scheduled_start_at AS Nullable(DateTime64(3, 'UTC'))) AS `scheduled_start_at`,
    CAST(f.scheduled_end_at AS Nullable(DateTime64(3, 'UTC'))) AS `scheduled_end_at`,
    CAST(f.actual_event_at AS Nullable(DateTime64(3, 'UTC'))) AS `actual_event_at`,
    CAST(f.realization_status AS String) AS `realization_status`,
    CAST(f.is_demo_request AS Nullable(Bool)) AS `is_demo_request`,
    CAST(f.is_realized_demo AS Nullable(Bool)) AS `is_realized_demo`,
    CAST(if(f.is_demo_request and not f.is_source_deleted,f.created_at,NULL) AS Nullable(DateTime64(3, 'UTC'))) AS `request_counting_at`,
    CAST(f.demo_session_key AS Nullable(String)) AS `demo_session_key`,
    CAST(NULL AS Nullable(DateTime64(3, 'UTC'))) AS `demo_counting_at`,
    CAST(multiIf(f.is_source_deleted,0,f.action_type_id is null or (f.is_demo_request and f.created_at is null),NULL,f.is_demo_request,1,0) AS Nullable(UInt8)) AS `nb_demo_request_contribution`,
    CAST(NULL AS Nullable(UInt8)) AS `nb_realized_demo_contribution`,
    CAST(p.sale_type_id AS Nullable(Int64)) AS `sale_type_id`,
    CAST(p.sale_type_key AS Nullable(String)) AS `sale_type_key`,
    CAST(p.sale_type_version_key AS Nullable(String)) AS `sale_type_version_key`,
    CAST(ty.sale_type_label AS Nullable(String)) AS `sale_type_label`,
    CAST(f.employee_key AS Nullable(String)) AS `employee_key`,
    CAST(f.employee_version_key AS Nullable(String)) AS `employee_version_key`,
    CAST(em.employee_display_name AS Nullable(String)) AS `employee_display_name`,
    CAST(f.team_key AS Nullable(String)) AS `team_key`,
    CAST(f.team_version_key AS Nullable(String)) AS `team_version_key`,
    CAST(tm.team_name AS Nullable(String)) AS `team_name`,
    CAST(f.is_team_calculable AS Bool) AS `is_team_calculable`,
    CAST(f.calculation_status AS String) AS `calculation_status`,
    CAST(f.status_reason AS Nullable(String)) AS `status_reason`
from latest f left join {{ ref('fct_opportunity_period') }} p on f.model_run_id=p.model_run_id and f.tenant_id=p.tenant_id and f.opportunity_key=p.opportunity_key and if(f.is_demo_request,f.created_at,f.actual_event_at)>=p.valid_from_at and (p.valid_to_at is null or if(f.is_demo_request,f.created_at,f.actual_event_at)<p.valid_to_at) left join {{ ref('dim_sale_type') }} ty on p.model_run_id=ty.model_run_id and p.sale_type_version_key=ty.sale_type_version_key left join {{ ref('dim_company') }} co on f.model_run_id=co.model_run_id and f.company_version_key=co.company_version_key left join {{ ref('dim_employee') }} em on f.model_run_id=em.model_run_id and f.employee_version_key=em.employee_version_key left join {{ ref('dim_team') }} tm on f.model_run_id=tm.model_run_id and f.team_version_key=tm.team_version_key left join {{ ref('dim_action_type') }} at on f.model_run_id=at.model_run_id and f.action_type_version_key=at.action_type_version_key where f.model_run_id={{ ch_literal(var('model_run_id','parse_only')) }}),
